#!/bin/sh
# cpuprobe.sh - run a command under perf stat and emit CPU MEASURE lines (meant to run inside the measured container).
# usage: cpuprobe.sh [--sibling CPU] [--kernel] -- cmd [args...]
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'cpuprobe.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'cpuprobe.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  cat <<'USAGE'
usage: cpuprobe.sh [--sibling CPU] [--kernel] -- cmd [args...]
       cpuprobe.sh --help | --build | --version

Runs cmd under one `perf stat` invocation (default output mode, no big-number separators) and prints MEASURE
lines after the command exits, only when every source was read: any failure is a message on stderr and a
nonzero exit with no MEASURE lines. Needs perf in the image and counter access (in Docker on a host with
perf_event_paranoid=3: --cap-add PERFMON --cap-add SYS_ADMIN). The command's stdout and stderr pass through.
The exit status is the command's; a probe failure exits 1, a usage error 2.

  --sibling CPU   also report the busy fraction of CPU (a whole number, no leading zero) over the run
  --kernel        also report the kernel-mode counters instructions_k and cycles_k

Metrics (whole-process totals of the command and its children; milliseconds with three decimals):
  cpu_task_clock_ms   perf task-clock: the CPU time the command's threads ran
  cpu_user_ms         perf's "seconds user" line (the child's rusage user time)
  cpu_sys_ms          perf's "seconds sys" line (the child's rusage system time)
  instructions_u      retired user-mode instructions (instructions_k with --kernel: kernel mode)
  cycles_u            user-mode cycles (cycles_k with --kernel: kernel mode)
  cgroup_usage_ms     the container cgroup's cpu.stat usage_usec delta around the perf invocation; it includes
                      perf's and the shell's own start-up, so only a control-subtracted value is workload cost
  sibling_busy        busy fraction (0-1) of the --sibling CPU: /proc/stat delta of total - idle - iowait,
                      10 ms tick granularity. A CPU taken offline (online file reads 0, /proc/stat row absent)
                      is a valid observation: sibling_busy 0 and the stderr note "sibling offline".
Errors: perf missing; a counter refused (<not supported>, <not counted>); a missing or unparseable counter, user
or sys line; an unreadable cpu.stat; a --sibling CPU absent from /proc/stat whose online file is unreadable or
reads 1; a sibling interval with no elapsed ticks. --build/--version print the repo's last-commit id (-dirty if
modified, unknown without git).
USAGE
  exit 0
fi
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
build_id() {
  d=$(git --no-optional-locks -C "$HERE" rev-parse --show-toplevel 2>/dev/null) || d=
  [ -n "$d" ] || { echo unknown; return; }
  sha=$(git --no-optional-locks -C "$d" log -1 --format=%H -- "$d" 2>/dev/null) || sha=
  [ -n "$sha" ] || { echo unknown; return; }
  if [ -n "$(git --no-optional-locks -C "$d" status --porcelain --untracked-files=no -- "$d" 2>/dev/null)" ]; then echo "$sha-dirty"; else echo "$sha"; fi
}
case ${1:-} in
  --build|--version) build_id; exit 0 ;;
esac

usage() { echo "cpuprobe.sh: $*" >&2; echo "usage: cpuprobe.sh [--sibling CPU] [--kernel] -- cmd [args...] (try --help)" >&2; exit 2; }
fail() { echo "cpuprobe.sh: $*" >&2; exit 1; }

sib=; have_sib=0; kernel=0
while [ $# -gt 0 ]; do
  case $1 in
    --) shift; break ;;
    --kernel) kernel=1; shift ;;
    --sibling)
      [ $# -ge 2 ] || usage "--sibling needs a value"
      [ "$have_sib" = 0 ] || usage "--sibling given twice"
      case $2 in 0|[1-9]*) ;; *) usage "--sibling must be a whole number without leading zeros, got '$2'" ;; esac
      case $2 in *[!0-9]*) usage "--sibling must be a whole number without leading zeros, got '$2'" ;; esac
      sib=$2; have_sib=1; shift 2 ;;
    *) usage "unknown argument '$1'" ;;
  esac
done
[ $# -gt 0 ] || usage "missing command after --"

command -v perf >/dev/null 2>&1 || fail "perf not found (install linux-perf in the image)"

T=$(mktemp -d)
trap 'rm -rf "$T"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

CGSTAT=/sys/fs/cgroup/cpu.stat
cg_usec() { # prints usage_usec of the container cgroup
  v=$(awk '$1=="usage_usec" && $2 ~ /^[0-9]+$/ {print $2; found=1} END{exit !found}' "$CGSTAT" 2>/dev/null) || fail "cannot read usage_usec from $CGSTAT"
  echo "$v"
}
cpu_row() { # prints "total busy" for /proc/stat row cpuN, nothing when the row is absent
  awk -v c="cpu$sib" '$1==c { t=0; for (i=2;i<=9;i++) t+=$i; print t, t-$5-$6 }' /proc/stat
}

sib_mode=
if [ "$have_sib" = 1 ]; then
  row0=$(cpu_row) || fail "cannot read /proc/stat"
  if [ -n "$row0" ]; then
    sib_mode=online
  else
    onl=
    [ -r "/sys/devices/system/cpu/cpu$sib/online" ] && read -r onl <"/sys/devices/system/cpu/cpu$sib/online" || onl=
    case $onl in
      0) sib_mode=offline; echo "cpuprobe.sh: sibling offline (cpu$sib)" >&2 ;;
      1) fail "--sibling cpu$sib is online but absent from /proc/stat" ;;
      *) fail "--sibling cpu$sib is absent from /proc/stat and its online state is unreadable" ;;
    esac
  fi
fi

events=task-clock,instructions:u,cycles:u
[ "$kernel" = 0 ] || events=$events,instructions:k,cycles:k

cg0=$(cg_usec)
rc=0
perf stat --no-big-num -e "$events" -o "$T/perf" -- "$@" || rc=$?
cg1=$(cg_usec)

row1=
if [ "$sib_mode" = online ]; then
  row1=$(cpu_row) || fail "cannot read /proc/stat"
  [ -n "$row1" ] || fail "cpu$sib vanished from /proc/stat during the run (taken offline?)"
elif [ "$sib_mode" = offline ]; then
  read -r onl <"/sys/devices/system/cpu/cpu$sib/online" 2>/dev/null || onl=
  [ "$onl" = 0 ] || fail "cpu$sib changed state during the run (online file reads '$onl')"
fi

[ -s "$T/perf" ] || fail "perf wrote no output (the command may not have started)"
# one pass over perf's default-mode output; prints "name value" per metric, or "ERR message" and exits 1
if ! out=$(awk -v kernel="$kernel" '
  function bad(m) { print "ERR " m; err = 1; exit 1 }
  function num(s) { return s ~ /^[0-9]+([.][0-9]+)?$/ }
  { for (i = 1; i <= 3 && i <= NF; i++) { seen[$i] = $0 } }
  /^[ \t]*<not (supported|counted)>/ { bad("counter refused: " $0) }
  /seconds user/ { if (num($1)) u = $1 + 0; else bad("unparseable user line: " $0) }
  /seconds sys/ { if (num($1)) s = $1 + 0; else bad("unparseable sys line: " $0) }
  function ev(name, key, scale,    l, f, n) {
    l = ""; n = 0
    for (k in seen) if (k == name) { l = seen[k] }
    if (l == "") bad("counter " name " missing from perf output")
    split(l, f, " ")
    if (!num(f[1])) bad("counter " name " unparseable: " l)
    printf "%s %.3f\n", key, f[1] * scale
  }
  function evi(name, key) {
    l = ""; for (k in seen) if (k == name) l = seen[k]
    if (l == "") bad("counter " name " missing from perf output")
    split(l, f, " ")
    if (!(f[1] ~ /^[0-9]+$/)) bad("counter " name " unparseable: " l)
    printf "%s %s\n", key, f[1]
  }
  END {
    if (err) exit 1
    if (u == "") bad("no \"seconds user\" line in perf output (perf produced no counter report; see its message above)")
    if (s == "") bad("no \"seconds sys\" line in perf output")
    ev("task-clock", "cpu_task_clock_ms", 1)
    printf "cpu_user_ms %.3f\ncpu_sys_ms %.3f\n", u * 1000, s * 1000
    evi("instructions:u", "instructions_u"); evi("cycles:u", "cycles_u")
    if (kernel == 1) { evi("instructions:k", "instructions_k"); evi("cycles:k", "cycles_k") }
  }' "$T/perf"); then
  msg=$(printf '%s\n' "$out" | sed -n 's/^ERR //p' | head -n 1)
  fail "${msg:-cannot parse perf output}"
fi

lines=$(printf '%s\n' "$out" | awk '{ if ($1 ~ /_ms$/) printf "MEASURE %s %s ms\n", $1, $2; else printf "MEASURE %s %s\n", $1, $2 }')
lines="$lines
$(awk -v a="$cg0" -v b="$cg1" 'BEGIN { printf "MEASURE cgroup_usage_ms %.3f ms\n", (b - a) / 1000 }')"
if [ "$sib_mode" = online ]; then
  sb=$(awk -v a="$row0" -v b="$row1" 'BEGIN { split(a, x, " "); split(b, y, " "); dt = y[1] - x[1]; db = y[2] - x[2]
    if (dt <= 0) { print "ERR"; exit }; printf "%.4f\n", db / dt }')
  [ "$sb" != ERR ] || fail "no ticks elapsed on cpu$sib during the run (too short to sample its busy fraction)"
  lines="$lines
MEASURE sibling_busy $sb fraction"
elif [ "$sib_mode" = offline ]; then
  lines="$lines
MEASURE sibling_busy 0 fraction"
fi
printf '%s\n' "$lines"
exit "$rc"
